67	// Client-side guard: a mount path is copyable only if it's a plain absolute path
68	// (named Docker volumes and other non-paths are shown but never selected). The
69	// server re-validates every selected path against the strict allowlist regardless.
70	function isCopyablePath(p: string): boolean {
71	  return typeof p === "string" && p.startsWith("/") && !p.includes("..") && p.length > 1;
72	}
73	
74	// ---- Storage-guardrail helpers --------------------------------------------
75	const GiB = 1024 ** 3;
76	
77	/** Parse a human size label ("1.2G", "340M", "220 MB") into bytes. Mirrors the
78	 *  server's parseSizeLabel — kept local so the client never imports the ssh2-laden
79	 *  detection module. */
80	function parseSize(label: string): number {
81	  const m = /^([\d.]+)\s*([KMGT]?)/i.exec((label ?? "").trim());
82	  if (!m) return 0;
83	  const n = parseFloat(m[1]);
84	  const mult: Record<string, number> = { "": 1, K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };
85	  return n * (mult[m[2].toUpperCase()] ?? 1);
86	}
87	
88	/** Adaptive size formatter: GB for ≥1 GB, else MB. */
89	function fmtSize(bytes: number): string {
90	  if (!Number.isFinite(bytes) || bytes <= 0) return "0 MB";
91	  const g = bytes / GiB;
92	  if (g >= 1) return g >= 10 ? `${g.toFixed(0)} GB` : `${g.toFixed(1)} GB`;
93	  const mb = bytes / (1024 * 1024);
94	  return `${Math.max(1, Math.round(mb))} MB`;
95	}
96	
97	// ---- OS/architecture compatibility helpers --------------------------------
98	/** Collapse arch aliases so amd64≡x86_64 and arm64≡aarch64 compare equal. */
99	function normArch(a: string | null | undefined): string {
100	  const s = (a ?? "").toLowerCase();
101	  if (!s) return "";
102	  if (["x86_64", "amd64", "x64"].includes(s)) return "x86_64";
103	  if (["aarch64", "arm64"].includes(s)) return "arm64";
104	  if (s.startsWith("armv") || s === "armhf" || s === "arm") return "arm";
105	  if (["i386", "i686", "x86"].includes(s)) return "x86";
106	  return s;
107	}
108	
109	const FAMILY_IDS: Record<string, string[]> = {
110	  debian: ["debian", "ubuntu", "linuxmint", "pop", "raspbian", "devuan", "kali", "elementary", "zorin"],
111	  rhel: ["rhel", "centos", "almalinux", "rocky", "fedora", "ol", "oracle", "amzn", "scientific", "cloudlinux"],
112	  suse: ["opensuse", "opensuse-leap", "opensuse-tumbleweed", "sles", "suse"],
113	  arch: ["arch", "manjaro", "endeavouros"],
114	  alpine: ["alpine"],
115	};
116	const FAMILY_LABEL: Record<string, string> = {
117	  debian: "Debian / Ubuntu",
118	  rhel: "RHEL / CentOS / Alma / Rocky",
119	  suse: "openSUSE / SLES",
120	  arch: "Arch",
121	  alpine: "Alpine",
122	  other: "another",
123	};
124	/** Map an os-release ID (or an osTemplate family string) to a distro family key. */
125	function familyOf(id: string | null | undefined): string {
126	  const s = (id ?? "").toLowerCase();
127	  if (!s) return "";
128	  for (const [fam, ids] of Object.entries(FAMILY_IDS)) if (ids.includes(s)) return fam;
129	  return "other";
130	}
131	
132	/** Pick the closest OS template to the source distro: same family first (prefer a
133	 *  matching major version), else nothing. Returns the template or null. */
134	function closestOsTemplate(
135	  sourceId: string,
136	  sourceVersion: string,
137	  templates: OsTemplateOption[]
138	): OsTemplateOption | null {
139	  const fam = familyOf(sourceId);
140	  if (!fam || fam === "other") return null;
141	  const sameFamily = templates.filter((t) => familyOf(t.family) === fam);
142	  if (sameFamily.length === 0) return null;
143	  const srcMajor = (sourceVersion || "").split(".")[0];
144	  // Prefer an exact family + same-major-version match, else the same family.
145	  const exact = sameFamily.find((t) => (t.version || "").split(".")[0] === srcMajor && srcMajor);
146	  return exact ?? sameFamily[0];
147	}
