164	            }`}
165	          >
166	            {i < step ? "✓" : i + 1}
167	          </span>
168	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
169	          {i < STEPS.length - 1 && <span className="mx-1 text-slate-700">→</span>}
170	        </div>
171	      ))}
