185	/** A single pre-checked item row (web root / home dir / database). */
186	function CheckItem({
187	  checked,
188	  onToggle,
189	  title,
190	  sub,
191	  size,
192	  badge,
193	}: {
194	  checked: boolean;
195	  onToggle: () => void;
