214	        <div className="flex items-center gap-2">
215	          <span className="truncate font-mono text-xs text-slate-200">{title}</span>
216	          {badge}
217	        </div>
218	        {sub && <p className="truncate text-[11px] text-slate-500">{sub}</p>}
219	      </div>
220	      {size && <span className="shrink-0 text-xs font-medium text-slate-400">{size}</span>}
221	    </label>
222	  );
