224	
225	export function MigrationWizard({
226	  servers,
227	  osTemplates = [],
228	}: {
229	  servers: ServerOption[];
230	  osTemplates?: OsTemplateOption[];
231	}) {
232	  const [step, setStep] = useState(0);
233	  const [error, setError] = useState<string | null>(null);
234	  const [scanning, setScanning] = useState(false);
235	  const [submitting, setSubmitting] = useState(false);
236	  const [activeId, setActiveId] = useState<string | null>(null);
237	
238	  // Step 0 — destination
239	  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
240	  // Step 1 — source
241	  const [host, setHost] = useState("");
242	  const [port, setPort] = useState("22");
243	  const [user, setUser] = useState("root");
244	  const [password, setPassword] = useState("");
245	
246	  // Step 2 — detection results + selections
247	  const [scan, setScan] = useState<ScanResult | null>(null);
248	  const [sizing, setSizing] = useState<SizingVerdict | null>(null);
249	  // Target free-space + OS/arch probe (for storage & compatibility guardrails).
250	  // undefined = not yet fetched; a value with disk:null = probe failed (soft warn).
251	  const [targetInfo, setTargetInfo] = useState<TargetInfo | null | undefined>(undefined);
252	  const [webSel, setWebSel] = useState<Set<string>>(new Set());
253	  const [homeSel, setHomeSel] = useState<Set<string>>(new Set());
254	  const [appSel, setAppSel] = useState<Set<string>>(new Set());
255	  const [dockerSel, setDockerSel] = useState<Set<string>>(new Set());
256	  const [customPaths, setCustomPaths] = useState<string[]>([]);
257	  const [newPath, setNewPath] = useState("");
258	  // Explicit opt-in to spend an attached block-storage volume on Docker's data.
259	  // OFF by default and never flipped on automatically: while a volume holds
260	  // /var/lib/docker the server can't run without it, so it stops being the
261	  // portable, move-it-to-another-server add-on the Volumes page promises.
262	  const [useVolumeForDocker, setUseVolumeForDocker] = useState(false);
263	  // Per-migration SAFETY opt-ins (wizard "Advanced options"). All default OFF —
264	  // passed through to createMigration as `options`; the worker keeps every
265	  // safety default unless the customer ticks the box.
266	  const [overwriteTargetData, setOverwriteTargetData] = useState(false);
267	  const [renameClones, setRenameClones] = useState(false);
268	  const [copySshKeys, setCopySshKeys] = useState(false);
269	
270	  // Deep-link back into a migration's result view (?migration=<id>). Used when a
271	  // customer leaves for Cloudflare's consent screen from the completed-migration
272	  // panel — they come back to exactly where they were, not to a blank wizard.
273	  useEffect(() => {
274	    const id = new URLSearchParams(window.location.search).get("migration");
275	    if (id && /^[A-Za-z0-9_-]{6,64}$/.test(id)) setActiveId(id);
276	  }, []);
277	
278	  const hostValid = /^[a-zA-Z0-9.\-:[\]]+$/.test(host.trim()) && host.trim().length > 0;
279	  const portNum = Number(port);
280	  const portValid = Number.isInteger(portNum) && portNum >= 1 && portNum <= 65535;
281	  const canScan = hostValid && portValid && user.trim().length > 0 && password.length > 0;
282	
283	  async function runScan() {
284	    setError(null);
285	    setScanning(true);
286	    setTargetInfo(undefined);
287	    try {
288	      // Scan the source and probe the destination's free space in parallel.
289	      const [res, diskRes] = await Promise.all([
290	        scanSource({
291	          serverId,
292	          sourceHost: host.trim(),
293	          sourcePort: portNum,
294	          sourceUser: user.trim(),
295	          sourcePassword: password,
296	        }),
297	        targetDiskFree(serverId).catch(() => ({ info: undefined })),
298	      ]);
299	      if (res.error) {
300	        setError(res.error);
301	        return;
302	      }
303	      setTargetInfo(diskRes?.info ?? null);
304	      const s = res.scan!;
305	      setScan(s);
306	      setSizing(res.sizing ?? null);
307	      // Pre-check everything we found — the customer just unchecks what they don't want.
308	      setWebSel(new Set(s.webRoots.map((w) => w.path)));
309	      setHomeSel(new Set(s.homes.map((h) => h.path)));
310	      setAppSel(new Set(s.appDirs.map((a) => a.path)));
311	      // Docker bind-mount host paths are the container's data — pre-check the copyable ones.
312	      setDockerSel(new Set(s.containers.flatMap((c) => c.mounts.filter(isCopyablePath))));
313	      setCustomPaths([]);
314	      setStep(2);
315	    } catch {
316	      setError("Something went wrong while scanning. Please try again.");
317	    } finally {
318	      setScanning(false);
319	    }
320	  }
321	
322	  function toggle(set: Set<string>, key: string, apply: (s: Set<string>) => void) {
323	    const next = new Set(set);
324	    if (next.has(key)) next.delete(key);
325	    else next.add(key);
326	    apply(next);
327	  }
328	
329	  function addPath() {
330	    const p = newPath.trim();
331	    if (p && p.startsWith("/") && !customPaths.includes(p)) {
332	      setCustomPaths((list) => [...list, p]);
333	      setNewPath("");
334	    }
335	  }
336	
337	  const selectedPaths = useMemo(
338	    () => [...new Set([...webSel, ...homeSel, ...appSel, ...dockerSel, ...customPaths])],
339	    [webSel, homeSel, appSel, dockerSel, customPaths]
340	  );
341	  // Databases are auto-included whenever an engine is detected — no password, no
342	  // per-DB selection. We dump every database via root's local auth on the source.
343	  const detectedEngines = useMemo(
344	    () => [...new Set((scan?.engines ?? []).filter((e) => e.present).map((e) => e.engine))],
345	    [scan]
346	  );
347	  // Prerequisites we'll install on the new server, derived from what we found.
348	  const prereqs = useMemo(() => {
349	    const list: string[] = [];
350	    if (!scan) return list;
351	    if (detectedEngines.includes("mysql")) list.push("MySQL / MariaDB");
352	    if (detectedEngines.includes("postgres")) list.push("PostgreSQL");
353	    if (scan.containers.length > 0) list.push("Docker + Compose");
354	    const procBlob = [
355	      ...scan.ports.map((p) => p.proc || ""),
356	      ...scan.services.map((s) => s.name || ""),
357	    ]
358	      .join(" ")
359	      .toLowerCase();
360	    if (/nginx/.test(procBlob) || (!/apache|httpd/.test(procBlob) && scan.webRoots.length > 0)) list.push("nginx");
361	    if (/apache|httpd/.test(procBlob)) list.push("Apache");
362	    const rtBlob = [
363	      ...scan.appDirs.map((a) => a.runtime || ""),
364	      ...scan.ports.map((p) => p.proc || ""),
365	    ]
366	      .join(" ")
367	      .toLowerCase();
368	    if (/node|next|pm2/.test(rtBlob)) list.push("Node.js");
369	    if (/python|gunicorn|uvicorn|celery/.test(rtBlob)) list.push("Python 3");
370	    return [...new Set(list)];
371	  }, [scan, detectedEngines]);
372	
373	  const hasSelection = selectedPaths.length > 0 || detectedEngines.length > 0;
374	
375	  // ---- Storage guardrail — total to migrate vs. target free space ----------
376	  // Recomputes live as the customer checks/unchecks. Unknown-size items (custom
377	  // folders, Docker mounts) contribute 0; the DB estimate is added whenever an
378	  // engine is detected (databases are auto-included).
379	  /**
380	   * The move splits across two destinations, so we size them separately:
381	   *  - `fileBytes`   → the selected folders + databases, restored to their original
382	   *                    paths, i.e. onto the ROOT filesystem.
383	   *  - `dockerBytes` → Docker images (they unpack to roughly 2x while loading) plus
384	   *                    the NAMED VOLUMES they mount (copied verbatim, so no unpack
385	   *                    factor) plus working headroom, all of which live under
386	   *                    /var/lib/{docker,containerd} — the engine relocates those onto
387	   *                    an unused volume, but ONLY if the customer opts in to using it.
388	   * Nothing ever needs `fileBytes + dockerBytes` contiguously, so testing the
389	   * combined total against a single disk understates what actually fits.
390	   *
391	   * `dockerBytes` MUST mirror worker/migrate-real.ts' pre-flight
392	   * (`inv.imageBytes * IMAGE_OVERHEAD_FACTOR + inv.volumeBytes`, then `+ FS_HEADROOM`)
393	   * exactly, and the volume bytes MUST stay out of `f`: quoting less than the engine
394	   * demands refuses a committed migration, quoting more spends disk that was never
395	   * needed. Both directions have happened. test/migration-sizing.test.ts pins it.
396	   */
397	  const { fileBytes, dockerBytes, totalBytes } = useMemo(() => {
398	    if (!scan) return { fileBytes: 0, dockerBytes: 0, totalBytes: 0 };
399	    const byPath = new Map<string, number>();
400	    scan.webRoots.forEach((w) => byPath.set(w.path, parseSize(w.sizeLabel)));
401	    scan.homes.forEach((h) => byPath.set(h.path, parseSize(h.sizeLabel)));
402	    scan.appDirs.forEach((a) => byPath.set(a.path, parseSize(a.sizeLabel)));
403	    let f = 0;
404	    for (const p of selectedPaths) f += byPath.get(p) ?? 0;
405	    if (detectedEngines.length > 0) f += Math.max(0, scan.dbSizeBytes ?? 0);
406	    const imageBytes = Math.max(0, scan.dockerImageBytes ?? 0);
407	    const volumeBytes = Math.max(0, scan.dockerVolumeBytes ?? 0);
408	    const d = imageBytes > 0 || volumeBytes > 0 ? imageBytes * 2 + volumeBytes + 2 * GiB : 0;
409	    return { fileBytes: f, dockerBytes: d, totalBytes: f + d };
410	  }, [scan, selectedPaths, detectedEngines]);
411	
412	  const storage = useMemo(() => {
413	    const disk = targetInfo?.disk ?? null;
414	    // Capacity sitting in an unused volume — OFFERED, not counted. It is the
415	    // largest single volume (the engine uses exactly one and never combines
416	    // them), and it only becomes usable space once the customer opts in.
417	    const spareOffered = Math.max(0, targetInfo?.spareDiskBytes ?? 0);
418	    const spareCount = Math.max(0, targetInfo?.spareDiskCount ?? 0);
419	    if (!disk) {
420	      return {
421	        state: "unknown" as StorageState,
422	        avail: 0, rootAvail: 0, spare: 0, spareOffered, spareCount,
423	        total: 0, diskTotal: 0, used: 0, margin: 0, deficitGB: 0,
424	      };
425	    }
426	    // The volume counts as capacity ONLY with explicit consent. Without it the
427	    // fit test is root-only: taking a portable volume to make a migration fit is
428	    // the customer's decision, so the verdict must reflect what they actually
429	    // chose rather than what we could do if we helped ourselves to their disk.
430	    const spare = useVolumeForDocker ? spareOffered : 0;
431	    const rootAvail = disk.availBytes;
432	    // Where each portion actually lands: files always on root; Docker's stores on
433	    // the volume when the customer opted in, otherwise also on root. Sizing the
434	    // two destinations separately is why opting in genuinely adds capacity even
435	    // though the root disk and the volume are separate filesystems.
436	    const dockerTarget = spare > 0 ? spare : rootAvail;
437	    const rootNeed = spare > 0 ? fileBytes : fileBytes + dockerBytes;
438	    const avail = spare > 0 ? rootAvail + spare : rootAvail;
439	    // Leave headroom for the OS/overhead: the larger of 2 GB or 10% of free space.
440	    const margin = Math.max(2 * GiB, rootAvail * 0.1);
441	    // The tighter of the two destinations decides the verdict.
442	    const rootSlack = rootAvail - rootNeed;
443	    const dockerSlack = dockerTarget - dockerBytes;
444	    const worstSlack = Math.min(rootSlack, dockerBytes > 0 ? dockerSlack : Infinity);
445	    let state: StorageState;
446	    if (worstSlack < 0) state = "wontfit";
447	    else if (worstSlack < margin) state = "tight";
448	    else state = "comfortable";
449	    // Extra space needed on whichever destination is short (data + margin).
450	    const deficitGB = Math.max(1, Math.ceil((margin - worstSlack) / GiB));
451	    return {
452	      state, avail, rootAvail, spare, spareOffered, spareCount,
453	      total: totalBytes, diskTotal: disk.totalBytes, used: disk.usedBytes, margin, deficitGB,
454	    };
455	  }, [targetInfo, totalBytes, useVolumeForDocker]);
456	
457	  // Hard block only when the data physically won't fit on the destination.
458	  const storageBlocks = storage.state === "wontfit";
459	
460	  // ---- OS / architecture compatibility (static — based on the scan) --------
461	  const compat = useMemo(() => {
462	    const items: CompatItem[] = [];
463	    const srcOs = scan?.sourceOs ?? null;
464	    const srcArch = scan?.sourceArch ?? null;
465	    const tgtArch = targetInfo?.arch ?? null;
466	    const tgtOs = targetInfo?.os ?? null;
467	
468	    const sa = normArch(srcArch);
469	    const ta = normArch(tgtArch);
470	    const archMismatch = !!sa && !!ta && sa !== ta;
471	
472	    const sFam = familyOf(srcOs?.id);
473	    const tFam = familyOf(tgtOs?.id);
