1646	const MULTI_LABEL_SUFFIXES = [
1647	  "co.uk", "org.uk", "ac.uk", "gov.uk", "me.uk", "com.au", "net.au", "org.au",
1648	  "co.nz", "com.br", "com.mx", "com.ar", "co.za", "co.in", "co.jp", "com.sg",
1649	  "com.tr", "com.pl", "com.ua", "co.il", "co.kr", "com.cn", "com.hk", "com.tw",
1650	];
