1652	/** Best-effort registrable zone for a hostname (`app.example.co.uk` → `example.co.uk`). */
1653	function zoneGuess(host: string): string {
1654	  const labels = host.split(".").filter(Boolean);
1655	  if (labels.length <= 2) return labels.join(".");
1656	  const lastTwo = labels.slice(-2).join(".");
1657	  return MULTI_LABEL_SUFFIXES.includes(lastTwo) ? labels.slice(-3).join(".") : lastTwo;
1658	}
